local I = table.create(128)
for i = 1, #A do I[string.byte(A, i)] = i - 1 end

local N = #P
local bytes = table.create(N // 4 * 3)
local n = 0
for i = 1, N, 4 do
	local v = 0
	for k = 0, 3 do
		v = v * 93 + (I[string.byte(P, i + k)] or 0)
	end
	bytes[n + 1] = math.floor(v / 65536) % 256
	bytes[n + 2] = math.floor(v / 256) % 256
	bytes[n + 3] = v % 256
	n = n + 3
end

local bxor = bit32.bxor
local KB = {string.byte(K, 1, #K)}
local function dec(i)
	return bxor(bytes[i], KB[(i - 1) % #K + 1], ((i - 1) * 31) % 256)
end

local len = dec(1) * 16777216 + dec(2) * 65536 + dec(3) * 256 + dec(4)
local parts = table.create(len)
for i = 1, len do parts[i] = string.char(dec(i + 4)) end

local chunk, err = loadstring(table.concat(parts), "=sonhub")
if not chunk then
	error("[SonHub] payload decode failed: " .. tostring(err))
end
return chunk()
